// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // No specific state needed for this property; just call version() directly
        string memory result = c.version();
        // Reference returns "1.0.0", bug returns "2.0.0"
        assertTrue(keccak256(abi.encodePacked(result)) == keccak256(abi.encodePacked("1.0.0")));
    }
}

