// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the depositor account as caller
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        // Call setL1BlockValues with a concrete _number value
        c.setL1BlockValues(42, 100, 200, bytes32(uint256(1)), 5, bytes32(uint256(2)), 300, 400);
        // After the call, reference stores number=42, mutant stores number=0
        assertTrue(c.number() == 42);
    }
}
